const entrada = $input.first().json;
if (typeof entrada.chatInput !== 'string' || !entrada.chatInput.trim() || entrada.chatInput.length > 1200) {
  throw new Error('ENTRADA_NO_VALIDA: envía una pregunta de 1 a 1200 caracteres.');
}
if (typeof entrada.sessionId !== 'string' || !entrada.sessionId.trim() || entrada.sessionId.length > 300) {
  throw new Error('SESION_NO_VALIDA: inicia una conversación desde Open chat.');
}
return [{ json: { chatInput: entrada.chatInput.trim(), sessionId: entrada.sessionId } }];

const recibido = $input.first().json;
const texto = typeof recibido.output === 'string' ? recibido.output.trim() : '';
return [{ json: { output: texto || 'No obtuve una respuesta utilizable. Revisa la ejecución antes de continuar.' } }];
